local _bxor = (bit32 and bit32.bxor) or (bit and bit.bxor)
local _byte = string.byte
local _char = string.char
local function I2u(enc_key, master)
  local o = {}
  local ml = #master
  for Mi = 1, #enc_key do
    o[Mi] = _char(_bxor(_byte(enc_key, Mi), _byte(master, ((Mi - 1) % ml) + 1)))
  end
  return table.concat(o)
end
local dCR = {}
for Mi = 0, 6 do
  dCR[Mi] = I2u(P6et[Mi], UIV)
end
local function R8x(cipher, key)
  local Dp = {}
  for Mi = 0, 255 do Dp[Mi] = Mi end
  local DF = 0
  local klen = #key
  for Mi = 0, 255 do
    DF = (DF + Dp[Mi] + _byte(key, (Mi % klen) + 1)) % 256
    Dp[Mi], Dp[DF] = Dp[DF], Dp[Mi]
  end
  Mi, DF = 0, 0
  local out = {}
  for SS = 1, #cipher do
    Mi = (Mi + 1) % 256
    DF = (DF + Dp[Mi]) % 256
    Dp[Mi], Dp[DF] = Dp[DF], Dp[Mi]
    out[SS] = _char(_bxor(_byte(cipher, SS), Dp[(Dp[Mi] + Dp[DF]) % 256]))
  end
  return table.concat(out)
end
-- Lazy string pool: decrypt on first index, cache, scrub ciphertext
local CUpB = {}
do
  local _raw = CUpB_raw
  local _bk = dCR
  local _bm = JIA
  local _sl = vhl
  local _dec = R8x
  setmetatable(CUpB, {
    __index = function(t, i)
      local c = _raw[i]
      if c == nil then return nil end
      local plain = _dec(c, _bk[_bm[i]] .. _char(_sl[i]))
      rawset(t, i, plain)
      _raw[i] = nil
      return plain
    end
  })
end
